import type { ReactNode } from 'react';

export function Tooltip({ label, children }: { label: string; children: ReactNode }) {
	return (
		<span className="group relative inline-flex">
			{children}
			<span role="tooltip" className="pointer-events-none absolute bottom-full left-1/2 mb-2 -translate-x-1/2 whitespace-nowrap rounded-sm bg-surface-inverse px-2 py-1 text-caption text-fg-inverse opacity-0 transition-opacity duration-150 ease-out group-focus-within:opacity-100 group-hover:opacity-100">{label}</span>
		</span>
	);
}
